import os
import json
from datetime import datetime
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


def extract_and_normalize_expense(document_path: str) -> str:
    endpoint = os.getenv("AZURE_FORM_RECOGNIZER_ENDPOINT")
    api_key = os.getenv("AZURE_FORM_RECOGNIZER_KEY")

    if not endpoint or not api_key:
        raise ValueError("AZURE_FORM_RECOGNIZER_ENDPOINT and AZURE_FORM_RECOGNIZER_KEY environment variables are required.")

    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key)
    )

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document("prebuilt-receipt", document=f)

    result = poller.result()

    if not result.documents:
        return json.dumps({"error": "No expense receipt detected in the provided document."}, indent=2)

    receipt = result.documents[0]
    fields = receipt.fields

    def safe_extract(field_name, default=None, cast_type=str):
        field = fields.get(field_name)
        if field and field.value is not None:
            try:
                if cast_type is float:
                    return float(field.value)
                elif cast_type is datetime:
                    return field.value.isoformat()
                else:
                    return str(field.value)
            except (ValueError, TypeError):
                return default
        return default

    line_items = []
    items_field = fields.get("Items")
    if items_field and items_field.value_type == "list":
        for item in items_field.value:
            item_data = item.value
            line_items.append({
                "description": item_data.get("Description", {}).value,
                "quantity": item_data.get("Quantity", {}).value,
                "price": item_data.get("TotalPrice", {}).value
            })

    normalized_schema = {
        "merchant_name": safe_extract("MerchantName", default="Unknown Merchant"),
        "transaction_date": safe_extract("TransactionDate", default=datetime.now().isoformat(), cast_type=datetime),
        "total_amount": safe_extract("Total", default=0.0, cast_type=float),
        "tax_amount": safe_extract("Tax", default=0.0, cast_type=float),
        "currency": safe_extract("Currency", default="USD"),
        "receipt_type": safe_extract("ReceiptType", default="Itemized"),
        "line_items": line_items
    }

    return json.dumps(normalized_schema, indent=2, ensure_ascii=False)
